const sd = $getWorkflowStaticData('global');
sd.skipped = [];
sd.deliveredReportIds = [];
sd.errors = [];
const body = $input.first().json || {};
const items = Array.isArray(body.items) ? body.items : [];
if (items.length === 0) {
  return [{ json: { empty: true } }];
}
return items.map((r) => ({
  json: {
    empty: false,
    report_id: r.id,
    customer_id: r.customer_id,
    payload: r.payload || {},
  },
}));

const report = $('لكل تقرير').item.json;
const customerResp = $json || {};
const customer = customerResp.customer || {};
const chatId = customer.telegram_chat_id;

if (!chatId) {
  return [{
    json: {
      skip: true,
      report_id: report.report_id,
      customer_id: report.customer_id,
      reason: 'no_telegram_chat_id',
    },
  }];
}

const payload = report.payload || {};
const fullText = String(payload.text || '').trim() || 'لا يوجد نص تقرير.';
const MAX_LEN = 3800; // هامش أمان تحت حد تيليجرام 4096 حرفًا

// تقسيم بحدود الأسطر لتفادي قطع سطر منتصفه
function splitText(text, maxLen) {
  const lines = text.split('\n');
  const chunks = [];
  let cur = '';
  for (const line of lines) {
    const candidate = cur ? cur + '\n' + line : line;
    if (candidate.length > maxLen && cur) {
      chunks.push(cur);
      cur = line;
    } else {
      cur = candidate;
    }
  }
  if (cur) chunks.push(cur);
  return chunks.length ? chunks : [text];
}

const chunks = splitText(fullText, MAX_LEN);

// أزرار 👎/🎉 لكل تقديم يحمل send_queue_id — اليوم هذا الحقل غير متوفر أبدًا
// بحمولة /admin/reports/pending (reports.py:_fetch_today_applications لا
// يُرجعه) — راجع NEEDS-CORE #1 بـn8n/README.md. الكود هنا متوافق مستقبليًا:
// إن أضافه المالك لاحقًا بـCore تظهر الأزرار تلقائيًا بلا أي تعديل هنا.
const apps = Array.isArray(payload.today_applications) ? payload.today_applications : [];
const withIds = apps.filter((a) => a && a.send_queue_id != null).slice(0, 50);

let keyboardRows = null;
if (withIds.length > 0) {
  // customer_id مُضمَّن بـcallback_data عمدًا (بديل عملي لعدم وجود نقطة
  // Core لرد chat_id إلى customer_id — راجع NEEDS-CORE #2). الصيغة:
  // fb:<customer_id>:<send_queue_id>:<thumbs_down|celebrate>
  keyboardRows = withIds.map((a) => ({
    row: {
      buttons: [
        {
          text: '👎',
          additionalFields: { callback_data: `fb:${report.customer_id}:${a.send_queue_id}:thumbs_down` },
        },
        {
          text: '🎉',
          additionalFields: { callback_data: `fb:${report.customer_id}:${a.send_queue_id}:celebrate` },
        },
      ],
    },
  }));
}

return chunks.map((text, idx) => ({
  json: {
    skip: false,
    report_id: report.report_id,
    customer_id: report.customer_id,
    chat_id: chatId,
    text,
    keyboardRows: idx === chunks.length - 1 ? keyboardRows : null,
    chunkIndex: idx,
    totalChunks: chunks.length,
  },
}));

const sd = $getWorkflowStaticData('global');
for (const item of $input.all()) {
  sd.skipped.push({ customer_id: item.json.customer_id, reason: item.json.reason });
}
return $input.all();

const items = $input.all();
const first = items[0] ? items[0].json : {};
const sd = $getWorkflowStaticData('global');
sd.deliveredReportIds.push(first.report_id);
return [{ json: { report_id: first.report_id } }];

const sd = $getWorkflowStaticData('global');
const summary = {
  delivered: (sd.deliveredReportIds || []).length,
  skipped_no_telegram: (sd.skipped || []).length,
  skipped_customers: sd.skipped || [],
};
return [{ json: { summary } }];
